107	// Docker keys credentials by host, so a Nexus instance with one repository
108	// logged into would otherwise send that login to every repository it serves.
109	func (b *RegistryBrowser) credsFor(entry browserRegistryEntry) (string, string) {
110		if !config.UsesCredentials(entry.authMode) {
111			return "", ""
112		}
113		// Credentials come from the parent registry, or the entry itself for a
114		// registry that is not a group member.
115		credURL := entry.URL
116		if entry.parentURL != "" {
117			credURL = entry.parentURL
118		}
119		var username string
120		for _, reg := range b.registries {
121			if reg.URL == credURL {
122				username = reg.Username
123				break
124			}
125		}
126		storedUser, storedPass, _ := docker.GetStoredCreds(credURL)
127		if username == "" {
128			username = storedUser
129		}
130		return username, storedPass
131	}
132	
133	// submitSearch validates the form and routes it: a name with no "/" is an
134	// image search when a Searcher is injected (level 1), anything else lists tags
135	// as before. An empty name starts nothing; no checked registry warns.
136	func (b *RegistryBrowser) submitSearch() (*RegistryBrowser, tea.Cmd) {
137		repo := strings.TrimSpace(b.repoInput.Value())
138		if repo == "" {
139			return b, nil
140		}
141		var entries []browserRegistryEntry
142		for _, entry := range b.entries {
143			if b.selected(entry) {
144				entries = append(entries, entry)
145			}
146		}
147		if len(entries) == 0 {
148			return b, func() tea.Msg { return RegistryBrowserWarnMsg{Text: "No registry selected"} }
149		}
150		if b.searcher != nil && !strings.Contains(repo, "/") {
151			return b.startImageSearch(repo, entries)
152		}
153		return b.startTagLookup(repo, entries)
154	}
155	
156	// entryAlias is the label a result of entry carries: the alias, behind its
157	// group's when it is a member.
158	func entryAlias(entry browserRegistryEntry) string {
159		if entry.ParentAlias != "" {
160			return entry.ParentAlias + "/" + entry.Alias
161		}
162		return entry.Alias
163	}
164	
165	// startTagLookup lists the tags of repo on every entry.
166	func (b *RegistryBrowser) startTagLookup(repo string, entries []browserRegistryEntry) (*RegistryBrowser, tea.Cmd) {
167		// Gather the requests first, then begin the lot: nothing is cancelled
168		// unless a request really starts.
169		type request struct {
170			entry                         browserRegistryEntry
171			alias, apiURL, repo, user, pw string
172		}
173		reqs := make([]request, 0, len(entries))
174		for _, entry := range entries {
175			username, storedPass := b.credsFor(entry)
176			// The prefix is applied here and nowhere else: it is then already part
177			// of MultiRegistryTag.Repo, so multiImageName and registryAPIURL need to
178			// know nothing about it. Teaching both would be two places free to
179			// drift, which is the disagreement D39 already is (§3.18).
180			normalizedRepo := joinRepoPrefix(entry.repoPrefix, normalizeRepoForRegistry(entry.URL, repo))
181			reqs = append(reqs, request{entry, entryAlias(entry), registryAPIURL(entry.URL), normalizedRepo, username, storedPass})
182		}
183	
184		ctx := b.beginRequests()
185		b.tags = nil
186		b.registryFilter = resultFilter{}
187		b.filterInput.SetValue("")
188		b.filterActive = false
189		// A new search starts from the default order, not wherever the last one's
190		// `.` presses left the table.
191		b.tagTable.SetSort(tagColumnTag, false)
192	
193		cmds := make([]tea.Cmd, 0, len(reqs))
194		for _, r := range reqs {
195			b.pendingSearches++
196			cmds = append(cmds, searchRegistryTagsCmd(ctx, b.gen, r.entry.key, r.entry.URL, r.alias, r.apiURL, r.repo, r.user, r.pw))
197		}
198	
199		b.state = browserStateTags
200		b.tagTable.Focus()
201		b.rebuildTagTable()
202		return b, tea.Batch(cmds...)
203	}
204	
205	func (b *RegistryBrowser) handleTagsKeyMsg(msg tea.KeyPressMsg) (*RegistryBrowser, tea.Cmd) {
206		if b.filterActive {
207			switch msg.String() {
208			case "esc", "enter":
209				b.filterActive = false
210				b.filterInput.Blur()
211				b.rebuildTagTable()
212				b.resizeTables()
213				return b, nil
214			}
215			return b.delegateUpdate(msg)
216		}
217	
218		switch msg.String() {
219		case "esc":
220			b.state = browserStateInput
221			b.tagTable.Blur()
222			b.updateFocus()
223			return b, nil
224		case "/":
225			b.filterActive = true
226			b.filterInput.Focus()
227			b.resizeTables()
228			return b, nil
229		case "r":
230			b.cycleRegistryFilter()
231			return b, nil
232		case "enter":
233			return b.openTagScanDetails()
234		case keymap.Get:
235			return b.pullSelectedTag()
236		case keymap.Scan:
237			return b.requestDirectScan()
238		}
239		// Navigation and `.` are the table's. `/` never reaches it: the browser's
240		// own filter took the key two cases above, and the table declares no
241		// searchable column, so it would decline it anyway.
242		return b, b.tagTable.Update(msg)
243	}
244

