87		if len(b.rows) > 0 {
88			sb.WriteString(theme.Bg("  ") + theme.DimStyle.Render("Registries:") + "\n")
89			for i, row := range b.rows {
90				focused := b.focusedField == b.brFieldReg(i)
91				if row.groupSlug != "" {
92					// One checkbox for the whole group, with a third state for a
93					// partial selection — eight proxies are not eight keystrokes.
94					sb.WriteString(theme.RenderCheckboxTri(b.groupState(row.groupSlug), row.label, focused))
95				} else {
96					sb.WriteString(theme.RenderCheckbox(b.selected(b.entries[row.entry]), row.label, focused))
97				}
98				if i < len(b.rows)-1 {
