147		if b.state == browserStateImages {
148			return b.searchTable.FilterBar().View()
149		}
150		borderStyle := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)
151	
152		var left string
153		if b.filterActive {
154			left = theme.KeyStyle.Render("/") + theme.Bg(" ") + b.filterInput.View()
155		} else if b.filterInput.Value() != "" {
