			},
			{
				Title: "Volumes Tab",
				Body:  "Lists " + engTitle + " volumes (Name, Driver, Mountpoint). Press N to create a new volume, D to remove the selected one, P to prune all unused volumes.",
			},
			{
				Title: "Registries Tab",
				Body: "Lists configured OCI registries. Press N to add a new registry, E to edit, U to log in or out, D to remove. Aliases shorten long registry URLs in the Images tab display. " +
					"The Logged column shows a warning instead of a check when the password sits in the engine's auth file (~/.docker/config.json, or podman's auth.json) rather than in a credential helper: " +
					"it is only base64 encoded there, readable by anything that can read the file. DevDesk did not put it there and cannot move it — configure credsStore or credHelpers, then log in again.",
			},
			{
				Title: "Registry Browser",
				Body: "Opened from the Images tab with 'b'. Type a repository name (e.g. nginx or library/nginx), " +
					"select which registries to search using Space, then press Browse Tags. " +
					"Results show tags from all selected registries concurrently. " +
					"Press 'r' to cycle the registry filter (one registry at a time), '/' to filter by tag name, '.' to sort. " +
					"Press G to pull the selected tag, S to scan it directly via Trivy (no pull), or Enter to view cached CVE details. " +
					"The first column is the activity dot: a scan or a pull of the tag running, queued or failed; the Critical, High, Medium and Low counts show an ellipsis while its scan runs. The footer says what the selected tag is doing. " +
					"Press Esc to go back to the search form. " +
					"An image search (level 1) lists one row per registry and image: the first column is the image icon, '/' filters by name, Esc closes the filter, then goes back to the form, and Enter does nothing yet.",
			},
			{
				Title: "Image Signatures",
				Body: "Every pull DevDesk makes — G, the registry browser, an agent over MCP — checks the image's signature first, with cosign (Tools tab). " +
					"The tag is resolved to a digest, that digest is verified, and that same digest is pulled then tagged, so the tag cannot move in between. " +
					"Rules come from ~/.devdesk/trust.yaml (yours, checked first), then a built-in list (distroless, Chainguard, Docker Hardened Images); with no rule, a new image must be signed by whoever signed the one you have. " +
					"A signature by an unexpected identity is always refused. An unsigned image is refused under a rule and only warned about otherwise; a check that could not run is refused under your own rules only. The footer names the rule behind a refusal. " +
					"Launching a container never pulls: an image arrives through a verified pull or not at all. " +
					"A pull typed in another terminal is not checked — DevDesk is not an admission controller. " +
					"Turn the check off per context by unticking Verify image signatures (scan tab of the configuration view); the header then says Signatures: off.",
			},
			{
				Title: "Launch Form",
				Body:  "When launching a container, ports are pre-filled from the image's EXPOSE metadata. Fill in environment variables and volume mounts as comma-separated lists. The container runs detached (-d) by default. An image that is not present locally is not pulled.",
			},
		},
	}
}
			return "docker.io/" + repo + ":" + tag
		}
		return repo + ":" + tag
	}
	return registryHost(registryURL) + "/" + repo + ":" + tag
}

func (b *RegistryBrowser) updateFocus() {
	b.repoInput.Blur()
	if b.focusedField == brFieldRepo {
		b.repoInput.Focus()
	}
}

// filteredMultiTags returns the tags the registry filter and the text filter let
// through. The order is the table's — it is what holds the cursor and the
// header arrow together.
func (b *RegistryBrowser) filteredMultiTags() []MultiRegistryTag {
	query := strings.ToLower(b.filterInput.Value())
	var result []MultiRegistryTag
	for _, t := range b.tags {
		if !b.registryFilter.matches(t.EntryKey, b.entryFor(t.EntryKey)) {
			continue
		}
		if query != "" && !strings.Contains(strings.ToLower(t.Tag), query) &&
			!strings.Contains(strings.ToLower(t.Repo), query) {
			continue
		}
		result = append(result, t)
	}
	return result
}

